begin
  if new.status = 'pending' then
    insert into notifications (recipient_id, type, title, body, entity_type, entity_id)
    select id, 'pending_approval',
      'New Registration: ' || new.name,
      new.email || ' has registered and is awaiting approval.',
      'rep', new.id
    from reps where role = 'manager' and status = 'active';
  end if;
  return new;
end;

declare
  v_rep_name text;
  v_company_name text;
begin
  select name into v_rep_name from reps where id = new.rep_id;
  select company_name into v_company_name from companies where id = new.company_id;

  insert into notifications (recipient_id, type, title, body, entity_type, entity_id)
  values (
    new.rep_id, 'assignment',
    'Company Assigned: ' || v_company_name,
    'You have been assigned to ' || v_company_name || ' as ' || new.role || '.',
    'company', new.company_id
  );
  return new;
end;

begin
  if new.classification = 'pending' then
    insert into notifications (recipient_id, type, title, body, entity_type, entity_id)
    select id, 'duplicate_alert',
